INSERT INTO "errata" ("id", "listing_id", "field", "before", "after", "reason", "evidence", "created_by", "created_at", "active", "reverted_at") VALUES (1, 589, 'year', 2024, 2018, 'Listed as 2024 but it is a 2018 car: the dealer''s year contradicts the 18 plate (Mar-Aug 2018), AutoTrader''s own vehicle data on the advert gives a May 2018 registration, and 74k miles, 3 owners and a manual gearbox (not offered on the 2024 Cooper) all fit 2018. Reported by the user.', 'https://www.autotrader.co.uk/car-details/202609035684979 (fetched 2026-10-18): page shows ''Registration 2024 (18 reg)''; page data has registrationDateFormatted ''May 2018'' and ''This vehicle has done 22,935 more miles than the average''', 'claude', '2026-10-18 19:34:09.976382', 1, NULL);
